InstructionDefinition.Payload:
// get office version installed on the client device i:e office 16, office xx etc
@getOffice          = "Select Name from SoftwareLicensingProduct where Name like '%Office%'";
@storeOfficeVersion = NativeServices.RunWmiQuery(Namespace:"root\\cimv2", Query:@getOffice);
@applicationName    = SELECT REGEXPCAPTURE("Office ..", Name) AS Application FROM @storeOfficeVersion LIMIT 1;

// Getting only numeric value version 
@extractVersion = FOREACH @an IN @applicationName 
    DO 
        SELECT REGEXPCAPTURE('\d{1,}', @an.Application) AS Capture from @an WHERE @an.Application IS NOT NULL;
    DONE;

// Check the version is equal to or greater than 15
@check = SELECT Capture FROM @extractVersion WHERE Capture == 16;

// Stop the execution if Office Package is Not Installed
IF NOT(@check)
    @results = SELECT "Unable to get Outlook version or Version is Not 16" as Data, 0 as Passed;
    RETURN @results;
ENDIF;

@checkNewOutlook= SELECT 'Software\\Microsoft\\Office\\' ||  Capture  || '.0\\Outlook\\Preferences' as key from @extractVersion;
@storeNewOutlook=NativeServices.RegistryKeyExists(Hive:"HKCU", Subkey:@checkNewOutlook.key);


@checkPreferencesKey=SELECT @storeNewOutlook.[Exists] FROM @storeNewOutlook where @storeNewOutlook.[Exists]==1;
IF (@checkPreferencesKey)
    @getNewOutlookValue=NativeServices.RegistryGetValue(Hive:"HKCU", Subkey:@checkNewOutlook.key, Name:"UseNewOutlook");
    IF NOT ( @getNewOutlookValue )
       @showResult = SELECT key || " UseNewOutlook Reg value does't exist" as Data, 0 as Passed FROM @checkNewOutlook;
       RETURN @showResult;
    ELSE
        @verifyNewOutlookValue = SELECT Value from @getNewOutlookValue where value==0;
        IF (@verifyNewOutlookValue)
            @showResult = SELECT key || " UseNewOutlook is set to " || Value as Data, 0 as Passed FROM @checkNewOutlook,@getNewOutlookValue;
            RETURN @showResult;
        ELSE
            @showResult = SELECT key || " UseNewOutlook is set to " || Value as Data, 1 as Passed FROM @checkNewOutlook,@getNewOutlookValue;
            RETURN @showResult;
        ENDIF;
    ENDIF;
ELSE
    @showResult = SELECT key || " doesnt exist" as Data, 0 as Passed FROM @checkNewOutlook;
    RETURN @showResult;
ENDIF;
